  function deleteProject() {
    console.log('Project deleted');
  }

  function confirmDelete() {
    Modal.confirm({
      title: '删除这个项目？',
      content: '此操作无法撤销。',
      danger: true,
      onOk: deleteProject,
    });
  }

  return <Button variant="danger" onClick={confirmDelete}>删除项目</Button>;
